class DwStatusBarManager extends StatefulWidget {
  final bool hasStatusBar;
  final bool isDarkIcons;
  final Color statusBarColor;
  final Widget child;

  const DwStatusBarManager({
    super.key,
    required this.hasStatusBar,
    required this.isDarkIcons,
    this.statusBarColor = Colors.transparent,
    required this.child,
  });

  @override
  State<DwStatusBarManager> createState() => _DwStatusBarManagerState();
}

class _DwStatusBarManagerState extends State<DwStatusBarManager> {
  @override
  void initState() {
    super.initState();
    _apply();
  }

  @override
  void didUpdateWidget(covariant DwStatusBarManager oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.hasStatusBar != widget.hasStatusBar ||
        oldWidget.isDarkIcons != widget.isDarkIcons ||
        oldWidget.statusBarColor != widget.statusBarColor) {
      _apply();
    }
  }

  void _apply() {
    if (!widget.hasStatusBar) {
      SystemChrome.setEnabledSystemUIMode(SystemUiMode.immersiveSticky);
    } else {
      SystemChrome.setEnabledSystemUIMode(SystemUiMode.edgeToEdge);
      SystemChrome.setSystemUIOverlayStyle(
        SystemUiOverlayStyle(
          statusBarColor: widget.statusBarColor,
          statusBarIconBrightness: widget.isDarkIcons ? Brightness.dark : Brightness.light,
          statusBarBrightness: widget.isDarkIcons ? Brightness.light : Brightness.dark,
        ),
      );
    }
  }

  @override
  void dispose() {
    SystemChrome.setEnabledSystemUIMode(SystemUiMode.edgeToEdge);
    SystemChrome.setSystemUIOverlayStyle(
      const SystemUiOverlayStyle(
        statusBarColor: Colors.transparent,
        statusBarIconBrightness: Brightness.dark,
        statusBarBrightness: Brightness.light,
      ),
    );
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => widget.child;
}




class DwActionValues {
  /// Converts [val] to a non-null Flutter Color.
  /// Supports:
  /// - [Color] instance
  /// - Signed 32-bit int (e.g. Android Sketchware color `-16776961` -> `0xFF0000FF`)
  /// - Unsigned 32-bit int (e.g. `0xFF1E88E5`)
  /// - 24-bit RGB int (e.g. `0x1E88E5` -> full alpha 0xFF1E88E5)
  /// - Hex strings with `#` or `0x` or raw (`#FF0000`, `#80FF0000`, `0xFF00FF`, `F00`, `FF0000`)
  /// - Decimal numeric strings (`"-16776961"`, `"4278190335"`)
  /// Throws [ArgumentError] with the quoted value for any invalid/empty/null input.
  static Color asColor(dynamic val) {
    if (val == null) {
      throw ArgumentError('Invalid color value: "$val"');
    }
