  static String _expandJavaReplacement(Match match, String replacement) {
    final buffer = StringBuffer();
    var i = 0;
    while (i < replacement.length) {
      final ch = replacement[i];
      if (ch == r'\' && i + 1 < replacement.length) {
        buffer.write(replacement[i + 1]);
        i += 2;
      } else if (ch == r'$' && i + 1 < replacement.length) {
        final nextCode = replacement.codeUnitAt(i + 1);
        if (nextCode >= 48 && nextCode <= 57) {
          var groupNum = nextCode - 48;
          var consumed = 2;
          if (i + 2 < replacement.length) {
            final secondCode = replacement.codeUnitAt(i + 2);
            if (secondCode >= 48 && secondCode <= 57) {
              final twoDigit = groupNum * 10 + (secondCode - 48);
              if (twoDigit <= match.groupCount) {
                groupNum = twoDigit;
                consumed = 3;
              }
            }
          }
          if (groupNum <= match.groupCount) {
            buffer.write(match.group(groupNum) ?? '');
          }
          i += consumed;
        } else {
          buffer.write(ch);
          i++;
        }
      } else {
        buffer.write(ch);
        i++;
      }
    }
    return buffer.toString();
  }
