  static List<String> splitRegExpIntoList(dynamic str, dynamic pattern) {
    final s = str?.toString() ?? '';
    final p = pattern?.toString() ?? '';
    if (p.isEmpty) {
      return s.split('');
    }
    try {
      final regExp = RegExp(p);
      if (!regExp.hasMatch(s)) {
        return <String>[s];
      }
      final parts = s.split(regExp).toList();
      while (parts.isNotEmpty && parts.last.isEmpty) {
        parts.removeLast();
      }
      return parts;
    } catch (_) {
      return <String>[s];
    }
  }
