  static String _roundHalfEven(num n, int maxFracDigits) {
    var s = n.toString();
    if (s.contains('e') || s.contains('E')) {
      s = n.toDouble().toStringAsFixed(maxFracDigits + 4);
    }
    final dotIdx = s.indexOf('.');
    var intPart = dotIdx == -1 ? s : s.substring(0, dotIdx);
    var fracPart = dotIdx == -1 ? '' : s.substring(dotIdx + 1);

    if (maxFracDigits == 0) {
      if (fracPart.isEmpty) return intPart;
      final firstFrac = int.parse(fracPart[0]);
      final rest = fracPart.length > 1 ? fracPart.substring(1) : '';
      final hasNonZeroRest = rest.runes.any((r) => r != 48); // '0' is 48
      bool roundUp = false;
      if (firstFrac > 5) {
        roundUp = true;
      } else if (firstFrac == 5) {
        if (hasNonZeroRest) {
          roundUp = true;
        } else {
          final lastIntDigit = intPart.isEmpty ? 0 : int.parse(intPart[intPart.length - 1]);
          roundUp = lastIntDigit % 2 != 0;
        }
      }
      if (roundUp) {
        final bigInt = BigInt.parse(intPart) + BigInt.one;
        intPart = bigInt.toString();
      }
      return intPart;
    }

    if (fracPart.length <= maxFracDigits) {
      return '$intPart.${fracPart.padRight(maxFracDigits, '0')}';
    }

    final decidingDigit = int.parse(fracPart[maxFracDigits]);
    final rest = fracPart.length > maxFracDigits + 1 ? fracPart.substring(maxFracDigits + 1) : '';
    final hasNonZeroRest = rest.runes.any((r) => r != 48);

    bool roundUp = false;
    if (decidingDigit > 5) {
      roundUp = true;
    } else if (decidingDigit == 5) {
      if (hasNonZeroRest) {
        roundUp = true;
      } else {
        final prevDigit = int.parse(fracPart[maxFracDigits - 1]);
        roundUp = prevDigit % 2 != 0;
      }
    }

    var keptFrac = fracPart.substring(0, maxFracDigits);
    if (roundUp) {
      final combined = BigInt.parse('$intPart$keptFrac') + BigInt.one;
      final combinedStr = combined.toString();
      if (combinedStr.length > (intPart.length + keptFrac.length)) {
        intPart = combinedStr.substring(0, combinedStr.length - maxFracDigits);
        keptFrac = combinedStr.substring(combinedStr.length - maxFracDigits);
      } else {
        final padded = combinedStr.padLeft(intPart.length + keptFrac.length, '0');
        intPart = padded.substring(0, intPart.length);
        keptFrac = padded.substring(intPart.length);
      }
    }
    return '$intPart.$keptFrac';
  }

  /// Formats a number according to a DecimalFormat pattern (e.g. "#,##0.00").
  /// Uses BigDecimal-like HALF_EVEN (banker's rounding) on the decimal string representation:
  /// - 2.5 with pattern "0" -> "2" (rounds to nearest even integer)
  /// - 3.5 with pattern "0" -> "4" (rounds to nearest even integer)
  /// - 0.125 with pattern "0.00" -> "0.12" (tie rounds to even last digit '2')
  /// Note: Values like 0.135 may occasionally differ if passed as binary IEEE-754 double
  /// due to precision limits in double representation, but decimal string representations
  /// are rounded strictly according to HALF_EVEN rules.
  static String toDecimalFormat(dynamic number, dynamic pattern) {
    final n = asNum(number);
    if (n == null) return number?.toString() ?? '';
    final p = pattern?.toString() ?? '';
    if (p.isEmpty) return formatNum(n).toString();
    try {
      final parts = p.split('.');
      final intPattern = parts[0];
      final fracPattern = parts.length > 1 ? parts[1] : '';
      final useGrouping = intPattern.contains(',');
      final minIntDigits = intPattern.replaceAll(RegExp(r'[^0]'), '').length;
      final minFracDigits = fracPattern.replaceAll(RegExp(r'[^0]'), '').length;
      final maxFracDigits = fracPattern.replaceAll(RegExp(r'[^0#]'), '').length;

      final isNegative = n < 0;
      var absVal = n.abs();

      String rawIntStr;
      String fracStr = '';

      if (maxFracDigits == 0) {
        rawIntStr = _roundHalfEven(absVal, 0);
      } else {
        final fixedStr = _roundHalfEven(absVal, maxFracDigits);
        final dotIdx = fixedStr.indexOf('.');
        if (dotIdx != -1) {
          rawIntStr = fixedStr.substring(0, dotIdx);
          var f = fixedStr.substring(dotIdx + 1);
          while (f.length > minFracDigits && f.endsWith('0')) {
            f = f.substring(0, f.length - 1);
          }
          fracStr = f;
        } else {
          rawIntStr = fixedStr;
        }
      }

      var intStr = rawIntStr;
      if (intStr.length < minIntDigits) {
        intStr = intStr.padLeft(minIntDigits, '0');
      }

      if (useGrouping) {
        final chars = intStr.split('');
        final buffer = StringBuffer();
        for (var i = 0; i < chars.length; i++) {
          if (i > 0 && (chars.length - i) % 3 == 0) {
            buffer.write(',');
          }
          buffer.write(chars[i]);
        }
        intStr = buffer.toString();
      }

      var result = (isNegative ? '-' : '') + intStr;
      if (fracStr.isNotEmpty) {
        result += '.$fracStr';
      }
      return result;
    } catch (_) {
      return formatNum(n).toString();
    }
  }
