    if (dt == 'number' || dt == 'num') {
      if (value is! num) {
        throw FormatException('$op: expected number element for List Number, but got ${value?.runtimeType ?? "null"}: $value');
      }
    } else if (dt == 'string') {
      if (value is! String) {
        throw FormatException('$op: expected String element for List String, but got ${value?.runtimeType ?? "null"}: $value');
      }
    } else if (dt == 'map') {
      if (value is! Map) {
        throw FormatException('$op: expected Map element for List Map, but got ${value?.runtimeType ?? "null"}: $value');
      }
    }
  }
  static List<dynamic> listAdd(dynamic list, dynamic value, [String? elementType]) {
    final l = list is List ? List<dynamic>.from(list) : <dynamic>[];
    final resolved = resolveJson(value);
