    l.add(resolved);
    return l;
  }
  static List<dynamic> listInsert(dynamic list, dynamic index, dynamic value, [String? elementType]) {
    final l = list is List ? List<dynamic>.from(list) : <dynamic>[];
    final resolved = resolveJson(value);
    _validateListElement(resolved, elementType, 'List Insert');
    final i = index is num ? index.toInt() : int.tryParse('$index') ?? l.length;
    l.insert(i.clamp(0, l.length), resolved);
    return l;
  }
