  static List<dynamic> listSort(dynamic list, [dynamic direction = 'ascending']) {
    final target = resolveJson(list);
    if (target is! List) throw const FormatException('List Sort: target is not a List.');
    if (target.isEmpty) return <dynamic>[];
    final isNum = target.every((e) => e is num);
    final isString = target.every((e) => e is String);
    if (!isNum && !isString) {
      throw const FormatException('List Sort: cannot sort list with mixed or non-comparable element types.');
    }
    final res = List<dynamic>.from(target);
    final isDesc = '$direction'.toLowerCase().trim() == 'descending' ||
        '$direction'.toLowerCase().trim() == 'desc';
    res.sort((a, b) {
      if (isNum) {
        return isDesc ? (b as num).compareTo(a as num) : (a as num).compareTo(b as num);
      }
      return isDesc ? '$b'.compareTo('$a') : '$a'.compareTo('$b');
    });
    return res;
  }
