  static List<dynamic> listSwap(dynamic list, dynamic index1, dynamic index2) {
    final target = resolveJson(list);
    if (target is! List) throw const FormatException('List Swap: target is not a List.');
    final i1 = index1 is num ? index1.toInt() : int.tryParse('$index1');
    final i2 = index2 is num ? index2.toInt() : int.tryParse('$index2');
    if (i1 == null || i2 == null) {
      throw const FormatException('List Swap: indices must be valid integers.');
    }
    if (i1 < 0 || i1 >= target.length || i2 < 0 || i2 >= target.length) {
      throw FormatException('List Swap: index out of bounds ($i1, $i2 for list of length ${target.length}).');
    }
    final res = List<dynamic>.from(target);
    final temp = res[i1];
    res[i1] = res[i2];
    res[i2] = temp;
    return res;
  }
  static List<dynamic> listAddAll(dynamic targetList, dynamic sourceList, [String? elementType]) {
    final target = resolveJson(targetList);
