    for (final item in source) {
      _validateListElement(item, elementType, 'List Add All');
    }
    final res = List<dynamic>.from(target);
    res.addAll(source);
    return res;
  }

  static bool evaluatePredicate(dynamic element, dynamic key, dynamic op, dynamic targetValue) {
    dynamic actual;
    final k = key?.toString().trim();
    if (element is Map && k != null && k.isNotEmpty) {
      if (element.containsKey(k)) {
        actual = element[k];
      } else {
        actual = null;
      }
    } else {
      actual = element;
    }

    final operatorStr = (op?.toString().trim() ?? '==');

    switch (operatorStr) {
      case '==':
        if (actual == null && targetValue == null) return true;
        if (actual == null || targetValue == null) return false;
        if (actual is num && targetValue is num) return actual == targetValue;
        final aNum = num.tryParse(actual.toString().trim());
        final tNum = num.tryParse(targetValue.toString().trim());
        if (aNum != null && tNum != null) return aNum == tNum;
        return actual.toString() == targetValue.toString();

      case '!=':
        return !evaluatePredicate(element, key, '==', targetValue);

      case '>':
      case '<':
      case '>=':
      case '<=':
        final aNum = actual is num ? actual : (actual != null ? num.tryParse(actual.toString().trim()) : null);
        final tNum = targetValue is num ? targetValue : (targetValue != null ? num.tryParse(targetValue.toString().trim()) : null);
        if (aNum != null && tNum != null) {
          if (operatorStr == '>') return aNum > tNum;
          if (operatorStr == '<') return aNum < tNum;
          if (operatorStr == '>=') return aNum >= tNum;
          return aNum <= tNum;
        }
        if (actual != null && targetValue != null) {
          final cmp = actual.toString().compareTo(targetValue.toString());
          if (operatorStr == '>') return cmp > 0;
          if (operatorStr == '<') return cmp < 0;
          if (operatorStr == '>=') return cmp >= 0;
          return cmp <= 0;
        }
        return false;

      case 'contains':
        if (actual == null) return false;
        if (actual is Iterable) return actual.contains(targetValue);
        return actual.toString().contains((targetValue ?? '').toString());

      case 'startsWith':
        if (actual == null) return false;
        return actual.toString().startsWith((targetValue ?? '').toString());

      default:
        return false;
    }
  }

  static List<dynamic> listFilter(dynamic list, dynamic key, dynamic op, dynamic targetValue) {
    final target = resolveJson(list);
    if (target is! List || target.isEmpty) return <dynamic>[];
    final result = <dynamic>[];
    for (final item in target) {
      if (evaluatePredicate(item, key, op, targetValue)) {
        result.add(item);
      }
    }
    return result;
  }

  static dynamic listFind(dynamic list, dynamic key, dynamic op, dynamic targetValue) {
