  static dynamic _deepClone(dynamic val) {
    if (val is Map) {
      return val.map((k, v) => MapEntry('$k', _deepClone(v)));
    }
    if (val is List) {
      return val.map((e) => _deepClone(e)).toList();
    }
    return val;
  }

  static bool _deepEquals(dynamic a, dynamic b) {
    if (identical(a, b)) return true;
    if (a is Map && b is Map) {
      if (a.length != b.length) return false;
      for (final key in a.keys) {
        if (!b.containsKey(key)) return false;
        if (!_deepEquals(a[key], b[key])) return false;
      }
      return true;
    }
    if (a is List && b is List) {
      if (a.length != b.length) return false;
      for (var i = 0; i < a.length; i++) {
        if (!_deepEquals(a[i], b[i])) return false;
      }
      return true;
    }
    return a == b;
  }

  static List<dynamic> listMapAddKeyValue(dynamic list, dynamic key, dynamic value, [String? dataType]) {
