    final i = index is num ? index.toInt() : int.tryParse('$index');
    if (i == null) throw const FormatException('List Map Insert: index must be a valid integer.');
    if (i < 0 || i > target.length) {
      throw FormatException('List Map Insert: index out of bounds ($i for list of length ${target.length}).');
    }
    final newMap = mapPut(<String, dynamic>{}, key, value, dataType);
    final res = List<dynamic>.from(target);
    res.insert(i, newMap);
    return res;
  }

  static List<dynamic> listMapSort(
    dynamic list,
    dynamic key, {
    dynamic isNumber = false,
    dynamic isAscending = true,
  }) {
    final target = resolveJson(list);
    if (target is! List) throw const FormatException('List Map Sort: target is not a List.');
    if (target.isEmpty) return <dynamic>[];
    for (var idx = 0; idx < target.length; idx++) {
      if (resolveJson(target[idx]) is! Map) {
        throw FormatException('List Map Sort: element at index $idx is not a Map.');
      }
    }
    final res = List<dynamic>.from(target);
    final numCompare = isNumber == true || '$isNumber'.toLowerCase().trim() == 'true';
    final asc = isAscending == true ||
        '$isAscending'.toLowerCase().trim() == 'true' ||
        '$isAscending'.toLowerCase().trim() == 'ascending';
    res.sort((a, b) {
      final ma = resolveJson(a) as Map;
      final mb = resolveJson(b) as Map;
      final va = ma['$key'];
      final vb = mb['$key'];
      if (va == null && vb == null) return 0;
      if (va == null) return asc ? -1 : 1;
      if (vb == null) return asc ? 1 : -1;
      if (numCompare) {
        final na = va is num ? va : num.tryParse('$va') ?? 0;
        final nb = vb is num ? vb : num.tryParse('$vb') ?? 0;
        return asc ? na.compareTo(nb) : nb.compareTo(na);
      } else {
        final sa = '$va';
        final sb = '$vb';
        return asc ? sa.compareTo(sb) : sb.compareTo(sa);
      }
    });
    return res;
  }

  static Map<String, dynamic> listMapGetToMap(dynamic list, dynamic index) {
    final target = resolveJson(list);
    if (target is! List) throw const FormatException('List Map Get To Map: target is not a List.');
    final i = index is num ? index.toInt() : int.tryParse('$index');
    if (i == null) throw const FormatException('List Map Get To Map: index must be a valid integer.');
    if (i < 0 || i >= target.length) {
      throw FormatException('List Map Get To Map: index out of bounds ($i for list of length ${target.length}).');
    }
    final item = resolveJson(target[i]);
    if (item is! Map) {
      throw FormatException('List Map Get To Map: element at index $i is not a Map.');
    }
    return Map<String, dynamic>.from(_deepClone(item) as Map);
  }

  static List<dynamic> listMapDeleteMap(dynamic list, dynamic map) {
    final target = resolveJson(list);
    if (target is! List) throw const FormatException('List Map Delete: target is not a List.');
    final targetMap = resolveJson(map);
    if (targetMap is! Map) throw const FormatException('List Map Delete: map to delete must be a Map.');
    final res = List<dynamic>.from(target);
    final idx = res.indexWhere((item) => _deepEquals(resolveJson(item), targetMap));
    if (idx != -1) {
      res.removeAt(idx);
    }
    return res;
  }

  static Map<String, dynamic> mapPut(dynamic map, dynamic key, dynamic value, [String? dataType]) {
    final target = resolveJson(map);
    final m = target is Map ? Map<String, dynamic>.from(target) : <String, dynamic>{};
    dynamic finalVal = resolveJson(value);
    if (dataType != null) {
      final dt = dataType.toLowerCase().replaceAll(' ', '');
      if (dt == 'int') {
        finalVal = finalVal is num ? finalVal.toInt() : int.tryParse('$finalVal') ?? finalVal;
      } else if (dt == 'double') {
        finalVal = finalVal is num ? finalVal.toDouble() : double.tryParse('$finalVal') ?? finalVal;
      } else if (dt == 'boolean' || dt == 'bool') {
        finalVal = finalVal is bool ? finalVal : (finalVal == 'true' || finalVal == true);
      } else if (dt == 'string') {
        finalVal = finalVal?.toString() ?? '';
      } else if (dt == 'map') {
        final res = resolveJson(finalVal);
        if (res is Map) {
          finalVal = Map<String, dynamic>.from(res);
        } else if (res == null) {
          finalVal = null;
        } else {
          throw FormatException('Map Put expected Map for key "$key", but got ${res.runtimeType}');
        }
      } else if (dt == 'list<string>' || dt == 'liststring' || dt == 'list_string') {
        final res = resolveJson(finalVal);
        if (res is List) {
          if (res.any((e) => e is! String)) {
            final bad = res.firstWhere((e) => e is! String);
            throw FormatException('Map Put expected every element of List<String> to be String for key "$key", but got ${bad.runtimeType}');
          }
          finalVal = List<String>.from(res);
        } else if (res == null) {
          finalVal = null;
        } else {
          throw FormatException('Map Put expected List<String> for key "$key", but got ${res.runtimeType}');
        }
      } else if (dt == 'list<map>' || dt == 'listmap' || dt == 'list_map') {
        final res = resolveJson(finalVal);
        if (res is List) {
          if (res.any((e) => e is! Map)) {
            final bad = res.firstWhere((e) => e is! Map);
            throw FormatException('Map Put expected every element of List<Map> to be Map for key "$key", but got ${bad.runtimeType}');
          }
          finalVal = res.map((e) => Map<String, dynamic>.from(e as Map)).toList();
        } else if (res == null) {
          finalVal = null;
        } else {
          throw FormatException('Map Put expected List<Map> for key "$key", but got ${res.runtimeType}');
        }
      }
    }
    m['$key'] = finalVal;
    return m;
  }
  static Map<String, dynamic> mapRemoveKey(dynamic map, dynamic key) {
    final target = resolveJson(map);
    final m = target is Map ? Map<String, dynamic>.from(target) : <String, dynamic>{};
    m.remove('$key');
    return m;
  }
  static Map<String, dynamic> mapClear() => <String, dynamic>{};
  static dynamic mapGet(dynamic map, dynamic key, [String? dataType]) {
    final target = resolveJson(map);
    if (target is! Map) return null;
    final raw = target['$key'];
    if (dataType == null) return raw;
    final dt = dataType.toLowerCase().replaceAll(' ', '');
    if (dt == 'number') {
      return raw is num ? raw : num.tryParse('$raw') ?? (raw is num ? raw : null);
    }
    if (dt == 'int') {
      return raw is num ? raw.toInt() : int.tryParse('$raw') ?? (raw is num ? raw.toInt() : null);
    }
    if (dt == 'double') {
      return raw is num ? raw.toDouble() : double.tryParse('$raw') ?? (raw is num ? raw.toDouble() : null);
    }
    if (dt == 'boolean' || dt == 'bool') {
      return raw is bool ? raw : (raw == 'true' || raw == true);
    }
    if (dt == 'string') {
      return raw?.toString() ?? '';
    }
    if (dt == 'map') {
      final res = resolveJson(raw);
      if (res is Map) return Map<String, dynamic>.from(res);
      if (res == null) return null;
      throw FormatException('Map Get expected Map for key "$key", but got ${res.runtimeType}');
    }
    if (dt == 'list<string>' || dt == 'liststring' || dt == 'list_string') {
      final res = resolveJson(raw);
      if (res is List) {
        if (res.any((e) => e is! String)) {
          final bad = res.firstWhere((e) => e is! String);
          throw FormatException('Map Get expected every element of List<String> to be String for key "$key", but got ${bad.runtimeType}');
        }
        return List<String>.from(res);
      }
      if (res == null) return null;
      throw FormatException('Map Get expected List<String> for key "$key", but got ${res.runtimeType}');
    }
    if (dt == 'list<map>' || dt == 'listmap' || dt == 'list_map') {
      final res = resolveJson(raw);
      if (res is List) {
        if (res.any((e) => e is! Map)) {
          final bad = res.firstWhere((e) => e is! Map);
          throw FormatException('Map Get expected every element of List<Map> to be Map for key "$key", but got ${bad.runtimeType}');
        }
        return res.map((e) => Map<String, dynamic>.from(e as Map)).toList();
      }
      if (res == null) return null;
      throw FormatException('Map Get expected List<Map> for key "$key", but got ${res.runtimeType}');
    }
    return raw;
  }
