  static String toJson(dynamic value) {
    final resolved = resolveJson(value);
    if (resolved == null) return '';
    if (resolved is String) return resolved;
    try {
      return jsonEncode(resolved);
    } catch (_) {
      return '';
    }
  }

  static Map<String, dynamic> jsonToMap(dynamic jsonStr, [dynamic currentMap]) {
    final fallback = currentMap is Map
        ? Map<String, dynamic>.from(currentMap)
        : (currentMap is Map<String, dynamic> ? currentMap : <String, dynamic>{});
    if (jsonStr == null) return fallback;
    try {
      final decoded = jsonStr is String ? jsonDecode(jsonStr.trim()) : resolveJson(jsonStr);
      if (decoded is Map) {
        return Map<String, dynamic>.from(decoded);
      }
    } catch (_) {}
    return fallback;
  }

  static List<Map<String, dynamic>> jsonToListMap(dynamic jsonStr, [dynamic currentList]) {
    final fallback = currentList is List
        ? [for (final item in currentList) if (resolveJson(item) is Map) Map<String, dynamic>.from(resolveJson(item) as Map)]
        : <Map<String, dynamic>>[];
    if (jsonStr == null) return fallback;
    try {
      final decoded = jsonStr is String ? jsonDecode(jsonStr.trim()) : resolveJson(jsonStr);
      if (decoded is List) {
        final result = <Map<String, dynamic>>[];
        for (final item in decoded) {
          final m = resolveJson(item);
          if (m is Map) {
            result.add(Map<String, dynamic>.from(m));
          } else {
            return fallback;
          }
        }
        return result;
      }
    } catch (_) {}
    return fallback;
  }

  static List<String> jsonToListString(dynamic jsonStr, [dynamic currentList]) {
    final fallback = currentList is List
        ? currentList.map((e) => e?.toString() ?? '').toList()
        : <String>[];
    if (jsonStr == null) return fallback;
    try {
      final decoded = jsonStr is String ? jsonDecode(jsonStr.trim()) : resolveJson(jsonStr);
      if (decoded is List) {
        return decoded.map((e) => e?.toString() ?? '').toList();
      }
    } catch (_) {}
    return fallback;
  }

  static List<num> jsonToListNumber(dynamic jsonStr, [dynamic currentList]) {
    final fallback = currentList is List
        ? [for (final item in currentList) if (asNum(item) != null) asNum(item)!]
        : <num>[];
    if (jsonStr == null) return fallback;
    try {
      final decoded = jsonStr is String ? jsonDecode(jsonStr.trim()) : resolveJson(jsonStr);
      if (decoded is List) {
        final result = <num>[];
        for (final item in decoded) {
          final n = asNum(item);
          if (n == null) {
            return fallback;
          }
          result.add(n);
        }
        return result;
      }
    } catch (_) {}
    return fallback;
  }

  // Math Batch A helpers
  static num mathGetDip(BuildContext? context, dynamic dp) {
    final v = asNum(dp) ?? 0;
    if (context != null) {
      final mq = MediaQuery.maybeOf(context);
      if (mq != null) return (v * mq.devicePixelRatio).toInt();
    }
    double ratio = 1.0;
    try {
      final view = WidgetsBinding.instance.platformDispatcher.views.firstOrNull;
      if (view != null) ratio = view.devicePixelRatio;
    } catch (_) {}
    return (v * ratio).toInt();
  }

  static num mathGetDisplayWidth(BuildContext? context) {
    if (context != null) {
      final mq = MediaQuery.maybeOf(context);
      if (mq != null) return formatNum(mq.size.width * mq.devicePixelRatio);
    }
    double width = 360.0;
    try {
      final view = WidgetsBinding.instance.platformDispatcher.views.firstOrNull;
      if (view != null) width = view.physicalSize.width;
    } catch (_) {}
    return formatNum(width);
  }

  static num mathGetDisplayHeight(BuildContext? context) {
    if (context != null) {
      final mq = MediaQuery.maybeOf(context);
      if (mq != null) return formatNum(mq.size.height * mq.devicePixelRatio);
    }
    double height = 640.0;
    try {
      final view = WidgetsBinding.instance.platformDispatcher.views.firstOrNull;
      if (view != null) height = view.physicalSize.height;
    } catch (_) {}
    return formatNum(height);
  }

  static const double mathPi = 3.1415926535897932;
  static const double mathE = 2.718281828459045;

  static num mathPow(dynamic base, dynamic exponent) {
    final b = asNum(base) ?? 0;
    final e = asNum(exponent) ?? 0;
    return formatNum(pow(b, e));
  }

  static num mathMin(dynamic a, dynamic b) {
    final na = asNum(a) ?? 0;
    final nb = asNum(b) ?? 0;
    if (na.isNaN || nb.isNaN) return double.nan;
    return formatNum(min(na, nb));
  }

  static num mathMax(dynamic a, dynamic b) {
    final na = asNum(a) ?? 0;
    final nb = asNum(b) ?? 0;
    if (na.isNaN || nb.isNaN) return double.nan;
    return formatNum(max(na, nb));
  }

  static num mathSqrt(dynamic a) {
    final na = asNum(a) ?? 0;
    if (na.isNaN || na < 0) return double.nan;
    return formatNum(sqrt(na));
  }

  static num mathAbs(dynamic a) {
    final na = asNum(a) ?? 0;
    if (na.isNaN) return double.nan;
    if (na.isInfinite) return na.abs();
    return formatNum(na.abs());
  }

  static num mathRound(dynamic a) {
    final na = asNum(a) ?? 0;
    if (na.isNaN) return 0;
    if (na.isInfinite) return na;
    return (na + 0.5).floor();
  }

  static num mathCeil(dynamic a) {
    final na = asNum(a) ?? 0;
    if (na.isNaN || na.isInfinite) return na;
    return na.ceil();
  }

  static num mathFloor(dynamic a) {
    final na = asNum(a) ?? 0;
    if (na.isNaN || na.isInfinite) return na;
    return na.floor();
  }
  // Math Batch B helpers
  static num mathSin(dynamic a) {
    final na = asNum(a) ?? 0;
    if (na.isNaN || na.isInfinite) return double.nan;
    return formatNum(sin(na));
  }

  static num mathCos(dynamic a) {
