  }

  static num mathAsin(dynamic a) {
    final na = asNum(a) ?? 0;
    if (na.isNaN || na < -1.0 || na > 1.0) return double.nan;
    return formatNum(asin(na));
  }

  static num mathAcos(dynamic a) {
    final na = asNum(a) ?? 0;
    if (na.isNaN || na < -1.0 || na > 1.0) return double.nan;
    return formatNum(acos(na));
  }

  static num mathAtan(dynamic a) {
    final na = asNum(a) ?? 0;
    if (na.isNaN) return double.nan;
    return formatNum(atan(na));
  }

  static num mathExp(dynamic a) {
    final na = asNum(a) ?? 0;
    if (na.isNaN) return double.nan;
    return formatNum(exp(na));
  }

  static num mathLog(dynamic a) {
    final na = asNum(a) ?? 0;
    if (na.isNaN || na < 0) return double.nan;
    if (na == 0) return double.negativeInfinity;
    return formatNum(log(na));
  }

  static num mathLog10(dynamic a) {
    final na = asNum(a) ?? 0;
    if (na.isNaN || na < 0) return double.nan;
    if (na == 0) return double.negativeInfinity;
    final raw = log(na) / ln10;
    final rounded = raw.round();
    if ((raw - rounded).abs() < 1e-12) {
      final p = pow(10.0, rounded);
      if (p == na || (p - na).abs() / (na == 0 ? 1 : na) < 1e-12) {
        return rounded;
      }
    }
    return formatNum(raw);
  }

  static num mathToRadian(dynamic deg) {
    final ndeg = asNum(deg) ?? 0;
    if (ndeg.isNaN || ndeg.isInfinite) return double.nan;
    return formatNum(ndeg * pi / 180.0);
  }

  static num mathToDegree(dynamic rad) {
    final nrad = asNum(rad) ?? 0;
    if (nrad.isNaN || nrad.isInfinite) return double.nan;
    return formatNum(nrad * 180.0 / pi);
  }

  // File Batch A helpers
  static String fileutilread(dynamic path) {
    try {
      final p = asString(path);
      if (p.isEmpty) return '';
      final f = File(p);
      if (!f.existsSync()) return '';
      return f.readAsStringSync();
    } catch (_) {
      return '';
    }
  }

  static void fileutilwrite(dynamic content, dynamic path) {
    try {
      final p = asString(path);
      if (p.isEmpty) return;
      final f = File(p);
      f.parent.createSync(recursive: true);
      f.writeAsStringSync(asString(content));
    } catch (_) {}
  }

  static void fileutilcopy(dynamic from, dynamic to) {
    try {
      final srcPath = asString(from);
      final destPath = asString(to);
      if (srcPath.isEmpty || destPath.isEmpty) return;
      final srcFile = File(srcPath);
      if (!srcFile.existsSync()) return;
      final destFile = File(destPath);
      destFile.parent.createSync(recursive: true);
      srcFile.copySync(destPath);
    } catch (_) {}
  }

  static void fileutilcopydir(dynamic from, dynamic to) {
    try {
      final srcPath = asString(from);
      final destPath = asString(to);
      if (srcPath.isEmpty || destPath.isEmpty) return;
      final srcDir = Directory(srcPath);
      if (!srcDir.existsSync()) return;

      final srcCanon = srcDir.absolute.path.replaceAll(r'\', '/');
      final destCanon = Directory(destPath).absolute.path.replaceAll(r'\', '/');
      if (destCanon == srcCanon || destCanon.startsWith('$srcCanon/')) {
        return;
      }

      final destDir = Directory(destPath);
      destDir.createSync(recursive: true);

      for (final entity in srcDir.listSync(recursive: true, followLinks: false)) {
        final rel = entity.path.replaceAll(r'\', '/').substring(srcCanon.length);
        final targetPath = '$destCanon$rel';
        if (entity is Directory) {
          Directory(targetPath).createSync(recursive: true);
        } else if (entity is File) {
          File(targetPath).parent.createSync(recursive: true);
          entity.copySync(targetPath);
        }
      }
    } catch (_) {}
  }

  static void fileutilmove(dynamic from, dynamic to) {
    try {
      final srcPath = asString(from);
      final destPath = asString(to);
      if (srcPath.isEmpty || destPath.isEmpty) return;
      final f = File(srcPath);
      if (f.existsSync()) {
        File(destPath).parent.createSync(recursive: true);
        try {
          f.renameSync(destPath);
        } catch (_) {
          f.copySync(destPath);
          f.deleteSync();
        }
        return;
      }
      final d = Directory(srcPath);
      if (d.existsSync()) {
        fileutilcopydir(srcPath, destPath);
        d.deleteSync(recursive: true);
      }
    } catch (_) {}
  }

  static void fileutildelete(dynamic path) {
    try {
      final pStr = asString(path).trim();
      if (pStr.isEmpty) return;

      // Explicit protection: reject root paths like "/", "\", "C:", "C:\"
      if (pStr == '/' || pStr == r'\' || RegExp(r'^[a-zA-Z]:[\\/]?$').hasMatch(pStr)) {
        return;
      }

      // Explicit protection: canonicalize with package:path to resolve "." and ".."
      final targetAbs = p.canonicalize(pStr).replaceAll(r'\', '/').toLowerCase();
      final projectAbs = p.canonicalize(Directory.current.path).replaceAll(r'\', '/').toLowerCase();
      final tempRootAbs = p.canonicalize(Directory.systemTemp.path).replaceAll(r'\', '/').toLowerCase();
      if (targetAbs == projectAbs ||
          projectAbs.startsWith('$targetAbs/') ||
          targetAbs == tempRootAbs) {
        return;
      }

      final type = FileSystemEntity.typeSync(pStr);
      if (type == FileSystemEntityType.file) {
        File(pStr).deleteSync(recursive: true);
      } else if (type == FileSystemEntityType.directory) {
        Directory(pStr).deleteSync(recursive: true);
      }
    } catch (_) {}
  }

  static void renameFile(dynamic from, dynamic to) {
    try {
      final srcPath = asString(from);
      final destPath = asString(to);
      if (srcPath.isEmpty || destPath.isEmpty) return;
      final type = FileSystemEntity.typeSync(srcPath);
      if (type == FileSystemEntityType.file) {
        final f = File(srcPath);
        File(destPath).parent.createSync(recursive: true);
        try {
          f.renameSync(destPath);
        } catch (_) {
          f.copySync(destPath);
          f.deleteSync();
        }
      } else if (type == FileSystemEntityType.directory) {
        final d = Directory(srcPath);
        Directory(destPath).parent.createSync(recursive: true);
        try {
          d.renameSync(destPath);
        } catch (_) {
          fileutilcopydir(srcPath, destPath);
          d.deleteSync(recursive: true);
        }
      }
    } catch (_) {}
  }

  static bool fileutilisexist(dynamic path) {
    try {
      final p = asString(path);
