  static dynamic fileutillistdir(dynamic path, dynamic targetList) {
    if (targetList == null) return targetList;
    try {
      final p = asString(path);
      if (p.isEmpty) return targetList;
      final dir = Directory(p);
      if (!dir.existsSync()) return targetList;
      final entries = <String>[];
      for (final entity in dir.listSync(followLinks: false)) {
        entries.add(entity.path);
      }
      if (targetList is List<String>) {
        final list = List<String>.from(targetList);
        list.clear();
        list.addAll(entries);
        return list;
      }
      if (targetList is List) {
        final list = List<dynamic>.from(targetList);
        list.clear();
        list.addAll(entries);
        return list;
      }
      return entries;
    } catch (_) {
      return targetList;
    }
  }

