  static void resizeBitmapFileWithRoundedBorder(
    dynamic fromPath,
    dynamic destPath,
    dynamic roundPixels,
  ) {
    try {
      final src = asString(fromPath);
      final dst = asString(destPath);
      final r = asNum(roundPixels)?.toInt() ?? 0;
      if (src.isEmpty || dst.isEmpty) return;
      final file = File(src);
      if (!file.existsSync()) return;
      final bytes = file.readAsBytesSync();
      final decoded = img.decodeImage(bytes);
      if (decoded == null) return;
      final w = decoded.width;
      final h = decoded.height;
      if (w <= 0 || h <= 0) return;
      final radius = r.clamp(0, (min(w, h) / 2).floor());
      if (radius > 0) {
        final result = decoded.hasAlpha ? decoded : decoded.convert(numChannels: 4);
        final rSq = radius * radius;
        for (var y = 0; y < h; y++) {
          for (var x = 0; x < w; x++) {
            bool maskOut = false;
            if (x < radius && y < radius) {
              final dx = radius - x - 1;
              final dy = radius - y - 1;
              if (dx * dx + dy * dy > rSq) maskOut = true;
            } else if (x >= w - radius && y < radius) {
              final dx = x - (w - radius);
              final dy = radius - y - 1;
              if (dx * dx + dy * dy > rSq) maskOut = true;
            } else if (x < radius && y >= h - radius) {
              final dx = radius - x - 1;
              final dy = y - (h - radius);
              if (dx * dx + dy * dy > rSq) maskOut = true;
            } else if (x >= w - radius && y >= h - radius) {
              final dx = x - (w - radius);
              final dy = y - (h - radius);
              if (dx * dx + dy * dy > rSq) maskOut = true;
            }
            if (maskOut) {
              result.setPixelRgba(x, y, 0, 0, 0, 0);
            }
          }
        }
        final outBytes = img.encodePng(result);
        final out = File(dst);
        out.parent.createSync(recursive: true);
        out.writeAsBytesSync(outBytes);
        return;
      }
      final outBytes = dst.toLowerCase().endsWith('.png') ? img.encodePng(decoded) : img.encodeJpg(decoded);
      final out = File(dst);
      out.parent.createSync(recursive: true);
      out.writeAsBytesSync(outBytes);
    } catch (_) {}
  }

  static void cropBitmapFileFromCenter(
    dynamic fromPath,
    dynamic destPath,
    dynamic width,
    dynamic height,
  ) {
    try {
      final src = asString(fromPath);
      final dst = asString(destPath);
      final w = asNum(width)?.toInt() ?? 0;
      final h = asNum(height)?.toInt() ?? 0;
      if (src.isEmpty || dst.isEmpty || w <= 0 || h <= 0) return;
      final file = File(src);
      if (!file.existsSync()) return;
      final bytes = file.readAsBytesSync();
      final decoded = img.decodeImage(bytes);
      if (decoded == null) return;
      final srcW = decoded.width;
      final srcH = decoded.height;
      final targetW = w.clamp(1, srcW);
      final targetH = h.clamp(1, srcH);
      final startX = ((srcW - targetW) / 2).round();
      final startY = ((srcH - targetH) / 2).round();
      final cropped = img.copyCrop(decoded, x: startX, y: startY, width: targetW, height: targetH);
      final outBytes = dst.toLowerCase().endsWith('.png') ? img.encodePng(cropped) : img.encodeJpg(cropped);
      final out = File(dst);
      out.parent.createSync(recursive: true);
      out.writeAsBytesSync(outBytes);
    } catch (_) {}
  }

