  static void skewBitmapFile(
    dynamic fromPath,
    dynamic destPath,
    dynamic x,
    dynamic y,
  ) {
    try {
      final src = asString(fromPath);
      final dst = asString(destPath);
      final kx = asNum(x)?.toDouble() ?? 0.0;
      final ky = asNum(y)?.toDouble() ?? 0.0;
      if (src.isEmpty || dst.isEmpty) return;
      final file = File(src);
      if (!file.existsSync()) return;
      final bytes = file.readAsBytesSync();
      final decoded = img.decodeImage(bytes);
      if (decoded == null) return;
      final srcW = decoded.width;
      final srcH = decoded.height;
      final tanX = kx.abs() > 2.0 ? tan(kx * pi / 180.0) : kx;
      final tanY = ky.abs() > 2.0 ? tan(ky * pi / 180.0) : ky;
      final newW = (srcW + (srcH * tanX.abs()).round()).clamp(1, 4096);
      final newH = (srcH + (srcW * tanY.abs()).round()).clamp(1, 4096);
      final result = img.Image(width: newW, height: newH, numChannels: decoded.numChannels);
      for (var sy = 0; sy < srcH; sy++) {
        for (var sx = 0; sx < srcW; sx++) {
          final nx = (sx + (tanX >= 0 ? sy * tanX : (srcH - sy) * (-tanX))).round().clamp(0, newW - 1);
          final ny = (sy + (tanY >= 0 ? sx * tanY : (srcW - sx) * (-tanY))).round().clamp(0, newH - 1);
          result.setPixel(nx, ny, decoded.getPixel(sx, sy));
        }
      }
      final outBytes = dst.toLowerCase().endsWith('.png') ? img.encodePng(result) : img.encodeJpg(result);
      final out = File(dst);
      out.parent.createSync(recursive: true);
      out.writeAsBytesSync(outBytes);
    } catch (_) {}
  }

  static void setBitmapFileColorFilter(
    dynamic fromPath,
    dynamic destPath,
    dynamic color,
  ) {
    try {
      final src = asString(fromPath);
      final dst = asString(destPath);
      final cVal = asNum(color)?.toInt() ?? 0;
      if (src.isEmpty || dst.isEmpty) return;
      final file = File(src);
      if (!file.existsSync()) return;
      final bytes = file.readAsBytesSync();
      final decoded = img.decodeImage(bytes);
      if (decoded == null) return;
      final r = (cVal >> 16) & 0xFF;
      final g = (cVal >> 8) & 0xFF;
      final b = cVal & 0xFF;
      final result = decoded.clone();
      for (final p in result) {
        p.r = (p.r * r / 255).round();
        p.g = (p.g * g / 255).round();
        p.b = (p.b * b / 255).round();
      }
      final outBytes = dst.toLowerCase().endsWith('.png') ? img.encodePng(result) : img.encodeJpg(result);
      final out = File(dst);
      out.parent.createSync(recursive: true);
      out.writeAsBytesSync(outBytes);
    } catch (_) {}
  }

  static void setBitmapFileBrightness(
    dynamic fromPath,
    dynamic destPath,
    dynamic value,
  ) {
    try {
      final src = asString(fromPath);
      final dst = asString(destPath);
      final v = asNum(value)?.toDouble() ?? 0.0;
      if (src.isEmpty || dst.isEmpty) return;
      final file = File(src);
      if (!file.existsSync()) return;
      final bytes = file.readAsBytesSync();
      final decoded = img.decodeImage(bytes);
      if (decoded == null) return;
      final factor = (1.0 + (v / 100.0)).clamp(0.0, 10.0);
      final adjusted = img.adjustColor(decoded, brightness: factor);
      final outBytes = dst.toLowerCase().endsWith('.png') ? img.encodePng(adjusted) : img.encodeJpg(adjusted);
      final out = File(dst);
      out.parent.createSync(recursive: true);
      out.writeAsBytesSync(outBytes);
    } catch (_) {}
  }

  static void setBitmapFileContrast(
    dynamic fromPath,
    dynamic destPath,
    dynamic value,
  ) {
    try {
      final src = asString(fromPath);
      final dst = asString(destPath);
      final v = asNum(value)?.toDouble() ?? 0.0;
      if (src.isEmpty || dst.isEmpty) return;
      final file = File(src);
      if (!file.existsSync()) return;
      final bytes = file.readAsBytesSync();
      final decoded = img.decodeImage(bytes);
      if (decoded == null) return;
      final contrastVal = (v <= 10.0 && v >= -100.0) ? (100.0 + v) : v;
      final adjusted = img.contrast(decoded, contrast: contrastVal.clamp(0.0, 200.0));
      final outBytes = dst.toLowerCase().endsWith('.png') ? img.encodePng(adjusted) : img.encodeJpg(adjusted);
      final out = File(dst);
      out.parent.createSync(recursive: true);
      out.writeAsBytesSync(outBytes);
    } catch (_) {}
  }

  static num getJpegRotate(dynamic path) {
    try {
      final pStr = asString(path).trim();
      if (pStr.isEmpty) return 0;
      final file = File(pStr);
      if (!file.existsSync()) return 0;
      final bytes = file.readAsBytesSync();
      final decoded = img.decodeImage(bytes);
      if (decoded == null) return 0;
      if (!decoded.exif.imageIfd.hasOrientation) return 0;
      final o = decoded.exif.imageIfd.orientation;
      if (o == 6) return 90;
      if (o == 3) return 180;
      if (o == 8) return 270;
      return 0;
    } catch (_) {
      return 0;
    }
  }

  static final Map<String, String> _assetStreams = {};

  static void getAssetFile(dynamic streamName, dynamic assetPath) {
    try {
      final s = asString(streamName).trim();
      final pStr = asString(assetPath).trim();
      if (s.isEmpty || pStr.isEmpty) return;
      _assetStreams[s] = pStr;
    } catch (_) {}
  }

  static String copyAssetFile(dynamic streamName) {
    try {
      final s = asString(streamName).trim();
      final pStr = _assetStreams[s] ?? s;
      if (pStr.isEmpty) return '';
      File f = File(pStr);
      if (!f.existsSync()) f = File('assets/$pStr');
      if (f.existsSync()) {
        return f.readAsStringSync();
      }
      return '';
    } catch (_) {
      return '';
    }
  }

  static bool fileCanExecute(dynamic path) {
    try {
      final pStr = asString(path).trim();
      if (pStr.isEmpty) return false;
      final file = File(pStr);
      if (!file.existsSync()) return false;
      if (Platform.isWindows) {
        final ext = pStr.toLowerCase();
        return ext.endsWith('.exe') || ext.endsWith('.bat') || ext.endsWith('.cmd') || ext.endsWith('.ps1');
      }
      final stat = file.statSync();
      return (stat.mode & 0x49) != 0;
    } catch (_) {
      return false;
    }
  }

  static bool fileCanRead(dynamic path) {
    try {
      final pStr = asString(path).trim();
      if (pStr.isEmpty) return false;
      final type = FileSystemEntity.typeSync(pStr);
      if (type == FileSystemEntityType.notFound) return false;
      if (type == FileSystemEntityType.file) {
        final f = File(pStr).openSync(mode: FileMode.read);
        f.closeSync();
        return true;
      }
      return Directory(pStr).existsSync();
    } catch (_) {
      return false;
    }
  }

  static bool fileCanWrite(dynamic path) {
    try {
      final pStr = asString(path).trim();
      if (pStr.isEmpty) return false;
      final type = FileSystemEntity.typeSync(pStr);
      if (type == FileSystemEntityType.notFound) {
        return File(pStr).parent.existsSync();
      }
      if (type == FileSystemEntityType.file) {
        final f = File(pStr).openSync(mode: FileMode.append);
        f.closeSync();
        return true;
      }
      return Directory(pStr).existsSync();
    } catch (_) {
      return false;
    }
  }

  static String fileGetName(dynamic path) {
    try {
      final pStr = asString(path).trim();
      if (pStr.isEmpty) return '';
      return p.basename(pStr);
    } catch (_) {
      return '';
    }
  }

  static String fileGetParent(dynamic path) {
    try {
      final pStr = asString(path).trim();
      if (pStr.isEmpty) return '';
      final parent = p.dirname(pStr);
      return (parent == '.' || parent == '/') ? '' : parent;
    } catch (_) {
      return '';
    }
  }

  static String fileGetPath(dynamic path) {
    try {
      return asString(path).trim();
    } catch (_) {
      return '';
    }
  }

  static bool fileIsHidden(dynamic path) {
    try {
      final pStr = asString(path).trim();
      if (pStr.isEmpty) return false;
      final name = p.basename(pStr);
      return name.startsWith('.');
    } catch (_) {
      return false;
    }
  }

  static String mockPickedPath = '';
  static String lastSharedPath = '';

  static String getDocumentsDir() {
    try {
      final sandbox = '${Directory.systemTemp.path}${Platform.pathSeparator}dw_preview_sandbox${Platform.pathSeparator}documents';
      final dir = Directory(sandbox);
      if (!dir.existsSync()) dir.createSync(recursive: true);
